(function () {
  'use strict';
  // Projected college cost of attendance. All costs are entered in today's dollars for one year;
  // nothing is built in. School year k (k = 0 .. years of study - 1) starts in (years until
  // college + k) years:
  //   tuition(k) = tuition today x (1 + tuition inflation)^(start + k)
  //   housing, books and other costs grow at the living-cost inflation rate the same way
  //   grants(k)  = grants today, or grants today x (1 + tuition inflation)^(start + k) if ticked
  //   net(k)     = max(0, cost(k) - grants(k))
  // Verified (Node, scratch tests, hand-checked): $10,000 tuition at 5% starting now for 1 year
  //   -> $10,000.00; starting in 5 years -> $10,000 x 1.05^5 = $12,762.82. Defaults ($12,000
  //   tuition at 5%, $13,000 housing + $1,200 books + $2,500 other at 3%, start in 5 years, 4 years,
  //   $3,000 fixed grants): year 1 = $15,315.38 + $19,359.88 = $34,675.26 gross; 4-year gross
  //   = sum over n = 5..8 of 12,000 x 1.05^n + 16,700 x 1.03^n = $66,011.20 + $80,994.50
  //   = $147,005.70, net $135,005.70 (independent Python check). 0% inflation gives today's costs x years; grants larger than
  //   the cost give $0 net. Whole script run under Node with a stub DOM: no NaN/Infinity.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function project(o) {
    var rows = [], gross = 0, net = 0, grants = 0;
    for (var k = 0; k < o.yearsIn; k++) {
      var n = o.yearsTo + k;
      var tf = Math.pow(1 + o.tuitionInfl, n), lf = Math.pow(1 + o.livingInfl, n);
      var tuition = o.tuition * tf, housing = o.housing * lf, books = o.books * lf, other = o.other * lf;
      var cost = tuition + housing + books + other;
      var aid = Math.min(cost, o.grants * (o.grantsGrow ? tf : 1));
      var netCost = cost - aid;
      gross += cost; net += netCost; grants += aid;
      rows.push({ year: k + 1, startsIn: n, tuition: tuition, living: housing + books + other, cost: cost, aid: aid, net: netCost });
    }
    return { rows: rows, gross: gross, net: net, grants: grants };
  }

  function readNum(id, blankValue) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    if (el.value === '' && blankValue !== undefined) return blankValue;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function fillTable(rows) {
    var body = document.getElementById('ccSchedule');
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (t) {
        var td = document.createElement('td');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function update() {
    var grantsGrowEl = document.getElementById('ccGrantsGrow');
    var o = {
      tuition: readNum('ccTuition', 0), housing: readNum('ccHousing', 0), books: readNum('ccBooks', 0),
      other: readNum('ccOther', 0), grants: readNum('ccGrants', 0), yearsTo: readNum('ccYearsTo'),
      yearsIn: readNum('ccYearsIn'), tuitionInfl: readNum('ccTuitionInfl', 0) / 100,
      livingInfl: readNum('ccLivingInfl', 0) / 100, grantsGrow: !!(grantsGrowEl && grantsGrowEl.checked)
    };
    var amounts = [o.tuition, o.housing, o.books, o.other, o.grants];
    var msg = '';
    if (amounts.some(function (v) { return !isFinite(v) || v < 0 || v > 1e9; })) msg = 'Enter yearly costs and grants of 0 or more.';
    else if (!isFinite(o.yearsTo) || o.yearsTo < 0 || o.yearsTo > 30 || Math.round(o.yearsTo) !== o.yearsTo) msg = 'Enter 0 to 30 whole years until college starts.';
    else if (!isFinite(o.yearsIn) || o.yearsIn < 1 || o.yearsIn > 8 || Math.round(o.yearsIn) !== o.yearsIn) msg = 'Enter 1 to 8 whole years of study.';
    else if ([o.tuitionInfl, o.livingInfl].some(function (v) { return !isFinite(v) || v < 0 || v > 0.2; })) msg = 'Enter cost increase rates from 0 to 20%.';
    var error = document.getElementById('ccError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) {
      ['ccNet', 'ccGross', 'ccGrantTotal', 'ccFirstYear', 'ccAverage', 'ccToday'].forEach(function (id) { set(id, '–'); });
      fillTable([]);
      return;
    }

    var r = project(o);
    var todayYear = o.tuition + o.housing + o.books + o.other;
    set('ccNet', money.format(r.net));
    set('ccGross', money.format(r.gross));
    set('ccGrantTotal', money.format(r.grants));
    set('ccFirstYear', money.format(r.rows[0].net));
    set('ccAverage', money.format(r.net / o.yearsIn));
    set('ccToday', money.format(todayYear * o.yearsIn));
    fillTable(r.rows.map(function (row) {
      return ['Year ' + row.year + (row.startsIn === 0 ? ' (starts now)' : ' (in ' + row.startsIn + (row.startsIn === 1 ? ' year)' : ' years)')),
        money.format(row.tuition), money.format(row.living), money.format(row.cost), money.format(row.aid), money.format(row.net)];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ccForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
